/* cast.js — draws the toon cast (Dot, Brick, Zip, Loop) on a canvas.
 * Shapes come from cast-shapes.js (generated by brand/build.py), so the demos match the brand SVGs.
 * Load after cast-shapes.js.
 *
 *   Cast.draw(ctx, 'dot', { x, y, h, mood, fill, ink, bg, look, blink, eyeScale, flip, arms, feet, trail })
 *     x, y      world position of the body's center        h      body height in px
 *     mood      'neutral' | 'happy' | 'surprised' | 'focused'
 *     fill      body color (a theme slot, e.g. DemoTheme.primary)   ink   outline/limb color (DemoTheme.ink)
 *     bg        surface color (Loop's hands)                        feat  face color; default: auto from fill
 *     look      {x, y} in −1…1: where the eyes glance               blink 0 (open) … 1 (shut)
 *     eyeScale  enlarge the eyes (Exaggeration)                      flip  mirror horizontally
 *     arms      Loop only: { r: {a, b}, l: {a, b} } shoulder/elbow angles in degrees (0 = hanging down)
 *     feet      Loop only, default true                             trail Zip only: draw speed-lines, default true
 *     only      'arms': draw just Loop's right arm (ghosted key poses)
 *   Cast.anchor(key, opts, [lx, ly]) → world point of a local point (e.g. Zip's tail, for speed-line chains)
 *   Cast.featFor(fill) → '#1A1A1A' or '#FFFFFF', whichever reads better on that body
 */
(function () {
  const S = window.CastShapes, INK = '#1A1A1A', paths = {};
  const P = (d) => (paths[d] ??= new Path2D(d));

  function lum(hex) {
    const n = parseInt(String(hex).replace('#', ''), 16);
    const c = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; });
    return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
  }
  // Features: dark ink on light bodies, white on dark bodies — whichever has more contrast.
  const featFor = (fill) => { const L = lum(fill); return (L + 0.05) / 0.05 >= 1.05 / (L + 0.05) ? INK : '#FFFFFF'; };

  function stroke(ctx, w, col, build) { ctx.beginPath(); build(); ctx.lineWidth = w; ctx.strokeStyle = col; ctx.stroke(); }

  function face(ctx, f, mood, feat, o, lw) {
    const [[lx, ly], [rx, ry]] = f.eyes, s = f.scale, [mx, my] = f.mouth, mw = f.mouth_w, w = 7 * s;
    const look = o.look || { x: 0, y: 0 }, blink = o.blink || 0, es = o.eyeScale || 1;
    const line = (pts, width = lw) => stroke(ctx, width, feat, () => { ctx.moveTo(pts[0], pts[1]); ctx.lineTo(pts[2], pts[3]); });
    const quad = (x0, y0, cx, cy, x1, y1, width = lw) => stroke(ctx, width, feat, () => { ctx.moveTo(x0, y0); ctx.quadraticCurveTo(cx, cy, x1, y1); });

    // brows
    const bl = [lx, ly - f.brow * Math.min(es, 1.6)], br = [rx, ry - f.brow * Math.min(es, 1.6)];
    if (mood === 'neutral') {
      if (f.neutral_brow === 'raised') { quad(bl[0] - w, bl[1] + 2, bl[0], bl[1] - 4, bl[0] + w, bl[1]); quad(br[0] - w, br[1], br[0], br[1] - 4, br[0] + w, br[1] + 2); }
      else if (f.neutral_brow === 'level') { line([bl[0] - w, bl[1] + 3, bl[0] + w, bl[1] + 3]); line([br[0] - w, br[1] + 3, br[0] + w, br[1] + 3]); }
      else { quad(bl[0] - w, bl[1] + 1, bl[0], bl[1] - 6, bl[0] + w, bl[1] - 1); line([br[0] - w, br[1] + 2, br[0] + w, br[1] + 3]); }
    } else if (mood === 'happy') { quad(bl[0] - w, bl[1], bl[0], bl[1] - 5, bl[0] + w, bl[1] - 1); quad(br[0] - w, br[1] - 1, br[0], br[1] - 5, br[0] + w, br[1]); }
    else if (mood === 'surprised') { quad(bl[0] - w, bl[1] - 3, bl[0], bl[1] - 11, bl[0] + w, bl[1] - 4); quad(br[0] - w, br[1] - 4, br[0], br[1] - 11, br[0] + w, br[1] - 3); }
    else { line([bl[0] - w, bl[1] + 3, bl[0] + w, bl[1] + 3.5]); line([br[0] - w, br[1] + 3.5, br[0] + w, br[1] + 3]); }

    // eyes
    const eye = (x, y, wink) => {
      if (mood === 'happy') { quad(x - 6 * s, y + 2 * s, x, y - 6 * s, x + 6 * s, y + 2 * s, lw + 0.4); return; }
      if (wink) { quad(x - 6 * s, y, x, y - 5 * s, x + 6 * s, y); return; }
      const big = (mood === 'surprised' ? 1.25 : 1) * es, open = Math.max(0.1, 1 - blink * 0.92);
      const gx = mood === 'focused' ? 0.38 : look.x * 0.32, gy = mood === 'focused' ? 0.3 : look.y * 0.28;
      if (f.eye === 'white') {
        const r = f.eye_r * big;
        ctx.beginPath(); ctx.ellipse(x, y, r, r * open, 0, 0, Math.PI * 2);
        ctx.fillStyle = '#FFFFFF'; ctx.fill(); ctx.lineWidth = 1.8; ctx.strokeStyle = feat; ctx.stroke();
        if (open > 0.35) {
          const pr = r * (mood === 'surprised' ? 0.5 : 0.46);
          ctx.beginPath(); ctx.arc(x + gx * r + 0.8, y + gy * r * open + 0.8, pr * Math.min(1, open * 1.3), 0, Math.PI * 2); ctx.fillStyle = feat; ctx.fill();
          if (f.glint) { ctx.beginPath(); ctx.arc(x + 2.2 * s + gx * r, y - 1.6 * s, 1.3 * s, 0, Math.PI * 2); ctx.fillStyle = '#FFFFFF'; ctx.fill(); }
        }
      } else {
        const r = f.eye_r * big;
        ctx.beginPath(); ctx.ellipse(x + gx * r * 1.2, y + gy * r, r, r * open, 0, 0, Math.PI * 2); ctx.fillStyle = feat; ctx.fill();
      }
    };
    eye(lx, ly, false); eye(rx, ry, mood === 'neutral' && f.wink && !o.noWink);

    // mouth
    if (mood === 'neutral') quad(mx - mw, my, mx, my + f.smile, mx + mw, my - (f.wink ? 1 : 0), lw + 0.2);
    else if (mood === 'happy') {
      ctx.beginPath(); ctx.moveTo(mx - mw - 2, my - 1); ctx.quadraticCurveTo(mx, my + mw * 1.5, mx + mw + 2, my - 1); ctx.closePath();
      ctx.fillStyle = feat; ctx.fill(); ctx.lineWidth = 1.5; ctx.strokeStyle = feat; ctx.stroke();
    } else if (mood === 'surprised') {
      ctx.beginPath(); ctx.ellipse(mx, my + 3, mw * 0.38 * Math.min(es, 1.5), mw * 0.52 * Math.min(es, 1.5), 0, 0, Math.PI * 2); ctx.fillStyle = feat; ctx.fill();
    } else {
      ctx.beginPath(); ctx.ellipse(mx + mw * 0.45, my + 5.1, 3.2 * s, 3.6 * s, 0, 0, Math.PI * 2);
      ctx.fillStyle = '#FF7A8A'; ctx.fill(); ctx.lineWidth = 1.6; ctx.strokeStyle = feat; ctx.stroke();
      line([mx - mw * 0.6, my + 2, mx + mw * 0.7, my + 2.5], lw + 0.2);
    }
  }

  const MOOD_ARMS = {   // Loop's default right/left arm poses (degrees from hanging down)
    neutral: { r: { a: 150, b: 15 }, l: { a: 50, b: -95 } }, happy: { r: { a: 125, b: 25 }, l: { a: 50, b: -95 } },
    surprised: { r: { a: 120, b: 20 }, l: { a: 120, b: 20 } }, focused: { r: { a: 45, b: -100 }, l: { a: 50, b: -95 } },
  };
  function arm(ctx, [sx, sy], side, { a, b }, ink, bg, lw) {
    const d = (deg) => (deg * Math.PI) / 180, L1 = 24, L2 = 22, dir = side === 'r' ? 1 : -1;
    const ex = sx + dir * Math.sin(d(a)) * L1, ey = sy + Math.cos(d(a)) * L1;
    const hx = ex + dir * Math.sin(d(a + b)) * L2, hy = ey + Math.cos(d(a + b)) * L2;
    stroke(ctx, lw, ink, () => { ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.lineTo(hx, hy); });
    ctx.beginPath(); ctx.arc(hx, hy, 4.5, 0, Math.PI * 2); ctx.fillStyle = bg; ctx.fill(); ctx.lineWidth = 2; ctx.strokeStyle = ink; ctx.stroke();
  }

  function transform(ctx, c, o) {
    const k = o.h / c.h;
    ctx.translate(o.x, o.y); ctx.scale(o.flip ? -k : k, k); ctx.translate(-c.cx, -c.cy);
    return k;
  }

  function draw(ctx, key, o) {
    const c = S[key], fill = o.fill || c.brand, ink = o.ink || INK, bg = o.bg || '#FFFFFF', mood = o.mood || 'neutral';
    const feat = o.feat || featFor(fill);
    ctx.save();
    const k = transform(ctx, c, o), lw = Math.max(2.4, 1.6 / k);       // lines never get thinner than ~1.6px on screen
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    if (o.only === 'arms' && key === 'loop') {                          // ghost poses: just the arms
      const arms = { ...MOOD_ARMS[mood], ...(o.arms || {}) };
      arm(ctx, c.shoulders[1], 'r', arms.r, ink, bg, lw); ctx.restore(); return;
    }
    if (key === 'zip' && o.trail !== false) {
      const [tx, ty] = c.tail;
      [[-8, -12, 14], [-14, 2, 18], [-6, 16, 12]].forEach(([dx, dy, l]) =>
        stroke(ctx, lw, ink, () => { ctx.moveTo(tx + dx, ty + dy); ctx.lineTo(tx + dx - l, ty + dy); }));
    }
    ctx.fillStyle = fill; ctx.fill(P(c.body));
    ctx.lineWidth = lw; ctx.strokeStyle = ink; ctx.stroke(P(c.outline));
    if (key === 'brick') stroke(ctx, lw + 1.2, ink, () => { ctx.moveTo(50, 178.5); ctx.bezierCurveTo(80, 180, 120, 180, 150, 178.5); });
    if (key === 'loop') {
      const arms = { ...MOOD_ARMS[mood], ...(o.arms || {}) };
      arm(ctx, c.shoulders[0], 'l', arms.l, ink, bg, lw); arm(ctx, c.shoulders[1], 'r', arms.r, ink, bg, lw);
      if (o.feet !== false) { ctx.fillStyle = ink; [90, 112].forEach((fx) => { ctx.beginPath(); ctx.ellipse(fx, 181, 8, 3.5, 0, 0, Math.PI * 2); ctx.fill(); }); }
    }
    face(ctx, c.face, mood, feat, o, lw);
    ctx.restore();
  }

  /** World coordinates of a point given in the character's 200×200 design space. */
  function anchor(key, o, [lx, ly]) {
    const c = S[key], k = o.h / c.h;
    return { x: o.x + (o.flip ? -1 : 1) * (lx - c.cx) * k, y: o.y + (ly - c.cy) * k };
  }

  window.Cast = { draw, anchor, featFor, shapes: S };
})();
